#!/usr/bin/env python3
"""Dependency-integrity checker for the buck2-nextest-adapter third-party graph.

Standard-library only (Python >= 3.11 for tomllib). Validates, structurally:

  * third-party/Cargo.lock: every package is pinned to the canonical crates.io
    registry with a non-empty sha256 checksum; git and path sources are
    rejected.
  * third-party/BUCK (generated by `reindeer buckify`): every registry package
    has exactly one http_archive carrying the canonical static.crates.io URL
    and a sha256 matching Cargo.lock; every archive is referenced by a
    generated rule; PUBLIC aliases exist exactly for the direct dependencies.
  * third-party/Cargo.toml: direct dependencies match the allowlist, are
    exact-pinned, and request only features that reindeer actually emitted.
  * third-party/reindeer-version.toml + reindeer.toml: the pinned Reindeer
    revision/repository and the canonical regeneration command.
  * third-party/dependency-note.toml: the auditable machine-readable note
    stays in sync with the lockfile and generated BUCK (version, checksum,
    features, rust-version-or-absent).

Usage:
  check_dependencies.py check <third-party-dir> [--registry-src DIR]
  check_dependencies.py update-note <third-party-dir> [--registry-src DIR]

`--registry-src DIR` points at a cargo registry source checkout (for example
~/.cargo/registry/src). `check` then additionally verifies the note's
rust-version claims against the crate Cargo.tomls; `update-note` uses it to
record real rust-version values. Without it, rust-version is recorded as
"absent" (the repository artifacts do not carry it).
"""

from __future__ import annotations

import ast
import re
import sys
import tomllib
from pathlib import Path

# Canonical pins for this repository's third-party graph.
ROOT_PACKAGE = "buck2-nextest-adapter-dependencies"
CANONICAL_SOURCE = "registry+https://github.com/rust-lang/crates.io-index"
CANONICAL_URL_TEMPLATE = "https://static.crates.io/crates/{name}/{version}/download"
REINDEER_REPOSITORY = "https://github.com/facebookincubator/reindeer"
REGENERATION_COMMAND = (
    "cd third-party && reindeer --manifest-path Cargo.toml --third-party-dir . buckify"
)
# Direct dependencies are exactly this set; adding a dependency requires an
# explicit decision here, in third-party/Cargo.toml, and a regeneration.
DIRECT_DEPENDENCIES = {
    "futures",
    "hyper-util",
    "libc",
    "prost",
    "prost-types",
    "quick-xml",
    "rustix",
    "serde",
    "serde_json",
    "sha2",
    "signal-hook",
    "tempfile",
    "tokio",
    "tokio-stream",
    "tonic",
    "tonic-prost",
    "tower",
}
# Registry packages that the pinned reindeer deliberately does not emit into
# the generated BUCK, so they must never appear as http_archive rules:
#   * windows_aarch64_*/windows_i686_*/windows_x86_64_gnullvm: the non-default
#     windows target-arch crates that reindeer prunes from windows-targets;
#   * version_check: build-dependency of generic-array that the pinned reindeer
#     does not emit a build script (and therefore no archive) for.
# Any other lock package missing from BUCK is an integrity error; any of these
# showing up in BUCK means reindeer behavior changed and the list must shrink.
REINDEER_OMITTED = {
    "version_check",
    "windows_aarch64_gnullvm",
    "windows_aarch64_msvc",
    "windows_i686_gnu",
    "windows_i686_gnullvm",
    "windows_i686_msvc",
    "windows_x86_64_gnullvm",
    "wasi",
}
NOTE_FORMAT_VERSION = 1
BUCK_GENERATED_HEADER = "# @generated by `reindeer buckify`"
CHECKSUM_RE = re.compile(r"^[0-9a-f]{64}$")
RUST_VERSION_RE = re.compile(r"^[0-9]+\.[0-9]+(\.[0-9]+)?([-+][0-9A-Za-z.-]+)?$")
SEMVER_RE = re.compile(r"^[0-9]+\.[0-9]+\.[0-9]+([-+][0-9A-Za-z.-]+)?$")


class IntegrityError(Exception):
    """Raised for a malformed input that the parser cannot recover from."""


# ---------------------------------------------------------------------------
# Structural parsing of the generated BUCK file.
# ---------------------------------------------------------------------------


class _DictValue:
    """A `{...}` or `dict(...)` value kept as raw text for targeted queries."""

    def __init__(self, raw: str):
        self.raw = raw


def _skip_string(text: str, start: int) -> int:
    """Return the index just past a `"..."` literal starting at `start`."""
    i = start + 1
    while i < len(text):
        ch = text[i]
        if ch == "\\":
            i += 2
            continue
        if ch == '"':
            return i + 1
        i += 1
    raise IntegrityError("unterminated string literal in BUCK")


def _match(text: str, start: int, open_ch: str, close_ch: str) -> int:
    """Return the index of the close bracket matching the one at `start`."""
    depth = 1
    i = start + 1
    while i < len(text):
        ch = text[i]
        if ch == '"':
            i = _skip_string(text, i)
            continue
        if ch == open_ch:
            depth += 1
        elif ch == close_ch:
            depth -= 1
            if depth == 0:
                return i
        i += 1
    raise IntegrityError(f"unbalanced '{open_ch}' in BUCK value")


def _split_top_level(text: str) -> list[str]:
    """Split on commas at bracket/paren/brace depth zero, string-aware."""
    parts: list[str] = []
    depth = 0
    current: list[str] = []
    i = 0
    while i < len(text):
        ch = text[i]
        if ch == '"':
            end = _skip_string(text, i)
            current.append(text[i:end])
            i = end
            continue
        if ch in "([{":
            depth += 1
        elif ch in ")]}":
            depth -= 1
        if ch == "," and depth == 0:
            parts.append("".join(current))
            current = []
        else:
            current.append(ch)
        i += 1
    if current:
        parts.append("".join(current))
    return parts


def _parse_value(text: str):
    text = text.strip()
    if text.endswith(","):
        text = text[:-1].rstrip()
    if not text:
        return None
    if text.startswith('"'):
        return ast.literal_eval(text)
    if text.startswith("["):
        end = _match(text, 0, "[", "]")
        values = []
        for part in _split_top_level(text[1:end]):
            parsed = _parse_value(part)
            if parsed is not None:
                values.append(parsed)
        return values
    if text.startswith("{") or text.startswith("dict("):
        return _DictValue(text)
    if text == "True":
        return True
    if text == "False":
        return False
    return ast.literal_eval(text)


def _parse_args(arg_text: str) -> dict[str, object]:
    """Parse top-level `key = value` pairs (4-space indent) of a rule call."""
    pairs: dict[str, object] = {}
    lines = arg_text.splitlines()
    key_re = re.compile(r"^    ([a-z_][a-z0-9_]*) = (.*)$")
    i = 0
    while i < len(lines):
        line = lines[i]
        if not line.strip() or line.strip().startswith("#"):
            i += 1
            continue
        match = key_re.match(line)
        if not match:
            i += 1
            continue
        key = match.group(1)
        value_lines = [match.group(2)]
        i += 1
        while i < len(lines):
            nxt = lines[i]
            if key_re.match(nxt):
                break
            if nxt and not nxt.startswith(" ") and nxt.strip():
                break
            value_lines.append(nxt)
            i += 1
        pairs[key] = _parse_value("\n".join(value_lines))
    return pairs


def _extract_feature_lists(text: str) -> list[str]:
    """Collect every `features = [...]` string list inside raw dict text."""
    features: set[str] = set()
    idx = 0
    needle = "features = ["
    while True:
        pos = text.find(needle, idx)
        if pos < 0:
            break
        end = _match(text, pos + len(needle) - 1, "[", "]")
        for match in re.finditer(r'"((?:[^"\\]|\\.)*)"', text[pos + len(needle):end]):
            features.add(match.group(1))
        idx = end + 1
    return sorted(features)


def parse_buck(path: Path) -> dict[str, object]:
    """Parse the generated BUCK file into structured rule records."""
    text = path.read_text(encoding="utf-8")
    if not text.startswith(BUCK_GENERATED_HEADER):
        raise IntegrityError(
            f"{path}: expected first line to be {BUCK_GENERATED_HEADER!r}"
        )
    archives: dict[str, dict[str, object]] = {}
    aliases: dict[str, dict[str, object]] = {}
    libraries: dict[str, dict[str, object]] = {}
    srcs_entries: set[str] = set()
    i = 0
    rule_re = re.compile(r"[A-Za-z_.][A-Za-z0-9_.]*")
    while i < len(text):
        if text[i].isspace() or text[i] == "#":
            if text[i] == "#":
                nl = text.find("\n", i)
                i = len(text) if nl < 0 else nl + 1
            else:
                i += 1
            continue
        match = rule_re.match(text, i)
        if not match:
            raise IntegrityError(f"{path}: cannot parse statement at offset {i}")
        rule = match.group(0)
        i = match.end()
        while i < len(text) and text[i].isspace():
            i += 1
        if i >= len(text) or text[i] != "(":
            raise IntegrityError(f"{path}: expected '(' after {rule}")
        open_paren = i
        close_paren = _match(text, open_paren, "(", ")")
        args = _parse_args(text[open_paren + 1:close_paren])
        name = args.get("name")
        if rule == "http_archive":
            if not isinstance(name, str):
                raise IntegrityError(f"{path}: http_archive without name")
            archives[name] = args
        elif rule == "alias":
            if not isinstance(name, str):
                raise IntegrityError(f"{path}: alias without name")
            aliases[name] = args
        elif rule == "cargo.rust_library":
            if not isinstance(name, str):
                raise IntegrityError(f"{path}: cargo.rust_library without name")
            libraries[name] = args
        srcs = args.get("srcs")
        if isinstance(srcs, list):
            for entry in srcs:
                if isinstance(entry, str):
                    srcs_entries.add(entry)
        i = close_paren + 1
    return {
        "archives": archives,
        "aliases": aliases,
        "libraries": libraries,
        "srcs_entries": srcs_entries,
    }


def emitted_features(library: dict[str, object]) -> tuple[list[str], list[str]]:
    """Return (base features, sorted union of platform features) for a library."""
    base = library.get("features")
    base_features = sorted(base) if isinstance(base, list) else []
    platform = library.get("platform")
    platform_features: list[str] = []
    if isinstance(platform, _DictValue):
        platform_features = _extract_feature_lists(platform.raw)
    return base_features, platform_features


# ---------------------------------------------------------------------------
# Loaders.
# ---------------------------------------------------------------------------


def load_toml(path: Path, label: str) -> dict[str, object]:
    try:
        with path.open("rb") as handle:
            return tomllib.load(handle)
    except FileNotFoundError:
        raise IntegrityError(f"{label}: missing file {path}")
    except tomllib.TOMLDecodeError as error:
        raise IntegrityError(f"{label}: invalid TOML in {path}: {error}")


def crate_dir(registry_src: Path, name: str, version: str) -> Path | None:
    """Locate a crate source checkout under a cargo registry src root."""
    for candidate in (
        registry_src / f"{name}-{version}",
        *(p for p in registry_src.glob(f"*/{name}-{version}")),
    ):
        if (candidate / "Cargo.toml").is_file():
            return candidate
    return None


def crate_rust_version(registry_src: Path, name: str, version: str) -> str | None:
    """Return the crate's rust-version, or None if absent/undeterminable."""
    directory = crate_dir(registry_src, name, version)
    if directory is None:
        return None
    try:
        with (directory / "Cargo.toml").open("rb") as handle:
            meta = tomllib.load(handle)
    except (OSError, tomllib.TOMLDecodeError):
        return None
    package = meta.get("package")
    if isinstance(package, dict):
        value = package.get("rust-version")
        if isinstance(value, str):
            return value
    return None


# ---------------------------------------------------------------------------
# The checks.
# ---------------------------------------------------------------------------


class Checker:
    def __init__(self, third_party: Path, registry_src: Path | None):
        self.dir = third_party
        self.registry_src = registry_src
        self.errors: list[str] = []
        self.lock = load_toml(third_party / "Cargo.lock", "Cargo.lock")
        self.manifest = load_toml(third_party / "Cargo.toml", "Cargo.toml")
        self.reindeer_version = load_toml(
            third_party / "reindeer-version.toml", "reindeer-version.toml"
        )
        self.reindeer_cfg = load_toml(third_party / "reindeer.toml", "reindeer.toml")
        self.buck = parse_buck(third_party / "BUCK")
        self.note = load_toml(third_party / "dependency-note.toml", "dependency-note.toml")

    def error(self, message: str) -> None:
        self.errors.append(message)

    # -- Cargo.lock ---------------------------------------------------------

    def check_lock(self) -> dict[tuple[str, str], dict[str, object]]:
        packages = self.lock.get("package")
        if not isinstance(packages, list) or not packages:
            self.error("Cargo.lock: no [[package]] entries")
            return {}
        by_key: dict[tuple[str, str], dict[str, object]] = {}
        for package in packages:
            if not isinstance(package, dict):
                self.error("Cargo.lock: malformed [[package]] entry")
                continue
            name = package.get("name")
            version = package.get("version")
            if not isinstance(name, str) or not isinstance(version, str):
                self.error("Cargo.lock: package without name/version")
                continue
            key = (name, version)
            if key in by_key:
                self.error(f"Cargo.lock: duplicate package {name} {version}")
            by_key[key] = package
            source = package.get("source")
            checksum = package.get("checksum")
            if source is None:
                if name != ROOT_PACKAGE:
                    self.error(
                        f"Cargo.lock: {name} {version} has no source; "
                        f"only the root package {ROOT_PACKAGE} may be source-less "
                        "(path dependencies are not allowed)"
                    )
                continue
            if not isinstance(source, str) or source != CANONICAL_SOURCE:
                self.error(
                    f"Cargo.lock: {name} {version} has non-canonical source "
                    f"{source!r}; expected {CANONICAL_SOURCE!r} "
                    "(git/path/other-registry sources are not allowed)"
                )
            if not isinstance(checksum, str) or not CHECKSUM_RE.fullmatch(checksum):
                self.error(
                    f"Cargo.lock: {name} {version} lacks a non-empty sha256 checksum"
                )
        return by_key

    # -- Cargo.toml direct dependencies -------------------------------------

    def check_manifest(self, lock: dict[tuple[str, str], dict[str, object]]) -> None:
        dependencies = self.manifest.get("dependencies")
        if not isinstance(dependencies, dict):
            self.error("Cargo.toml: missing [dependencies]")
            return
        names = set(dependencies)
        if names != DIRECT_DEPENDENCIES:
            extra = sorted(names - DIRECT_DEPENDENCIES)
            missing = sorted(DIRECT_DEPENDENCIES - names)
            if extra:
                self.error(
                    "Cargo.toml: direct dependencies not on the allowlist: "
                    + ", ".join(extra)
                )
            if missing:
                self.error(
                    "Cargo.toml: allowlisted dependencies missing: "
                    + ", ".join(missing)
                )
        aliases = self.buck["aliases"]
        libraries = self.buck["libraries"]
        for name, spec in sorted(dependencies.items()):
            if isinstance(spec, str):
                # Shorthand `name = "=1.2.3"` form: no features, default on.
                spec = {"version": spec}
            if not isinstance(spec, dict):
                self.error(f"Cargo.toml: dependency {name} must be a table")
                continue
            version = spec.get("version")
            if not isinstance(version, str) or not version.startswith("="):
                self.error(
                    f"Cargo.toml: dependency {name} must be exact-pinned "
                    f"(version = \"=<version>\"), got {version!r}"
                )
            else:
                pinned = version[1:]
                if not SEMVER_RE.fullmatch(pinned):
                    self.error(
                        f"Cargo.toml: dependency {name} has malformed pin {version!r}"
                    )
                lock_versions = {v for (n, v) in lock if n == name}
                if lock_versions != {pinned}:
                    self.error(
                        f"Cargo.toml: pin {name} {pinned} does not match "
                        f"Cargo.lock versions {sorted(lock_versions) or 'none'}"
                    )
            alias = aliases.get(name)
            if alias is None:
                self.error(f"Cargo.toml: direct dependency {name} has no PUBLIC alias")
            else:
                visibility = alias.get("visibility")
                if not (
                    isinstance(visibility, list) and "PUBLIC" in visibility
                ):
                    self.error(f"Cargo.toml: alias {name} is not PUBLIC")
                actual = alias.get("actual")
                library = (
                    libraries.get(actual[1:]) if isinstance(actual, str) else None
                )
                if library is None:
                    self.error(
                        f"Cargo.toml: alias {name} -> {actual!r} does not resolve "
                        "to a generated rust_library"
                    )
                    continue
                base_features, _ = emitted_features(library)
                requested = spec.get("features", [])
                if not isinstance(requested, list) or not all(
                    isinstance(f, str) for f in requested
                ):
                    self.error(f"Cargo.toml: dependency {name} features malformed")
                    requested = []
                for feature in requested:
                    if feature not in base_features:
                        self.error(
                            f"Cargo.toml: requested feature {name}/{feature} "
                            f"not emitted by reindeer (emitted: {base_features})"
                        )
                if spec.get("default-features") is False and "default" in base_features:
                    self.error(
                        f"Cargo.toml: {name} disables default features but "
                        "reindeer emitted \"default\""
                    )
        for alias_name in self.buck["aliases"]:
            if alias_name not in DIRECT_DEPENDENCIES:
                self.error(
                    f"BUCK: alias {alias_name} is not a direct dependency"
                )

    # -- BUCK archives vs Cargo.lock ----------------------------------------

    def check_archives(self, lock: dict[tuple[str, str], dict[str, object]]) -> None:
        archives = self.buck["archives"]
        expected_keys = set()
        for (name, version), package in lock.items():
            if "source" not in package:
                continue
            key = f"{name}-{version}.crate"
            expected_keys.add(key)
            archive = archives.get(key)
            if archive is None:
                if name not in REINDEER_OMITTED:
                    self.error(
                        f"BUCK: missing http_archive for {name} {version} ({key})"
                    )
                continue
            sha256 = archive.get("sha256")
            checksum = package.get("checksum")
            if sha256 != checksum:
                self.error(
                    f"BUCK: {key} sha256 {sha256!r} does not match "
                    f"Cargo.lock checksum {checksum!r}"
                )
            urls = archive.get("urls")
            canonical = [CANONICAL_URL_TEMPLATE.format(name=name, version=version)]
            if urls != canonical:
                self.error(
                    f"BUCK: {key} urls {urls!r} are not exactly the canonical "
                    f"{canonical}"
                )
            strip_prefix = archive.get("strip_prefix")
            if strip_prefix != f"{name}-{version}":
                self.error(
                    f"BUCK: {key} strip_prefix {strip_prefix!r} does not match "
                    f"{name}-{version}"
                )
        for key in archives:
            if key not in expected_keys:
                self.error(f"BUCK: http_archive {key} has no Cargo.lock package")
        lock_names_with_archives = {
            name
            for (name, version), package in lock.items()
            if "source" in package and f"{name}-{version}.crate" in archives
        }
        lock_registry_names = {
            name for (name, _), package in lock.items() if "source" in package
        }
        omitted = lock_registry_names - lock_names_with_archives
        if omitted != REINDEER_OMITTED:
            unexpected = sorted(omitted - REINDEER_OMITTED)
            now_emitted = sorted(REINDEER_OMITTED - omitted)
            if unexpected:
                self.error(
                    "BUCK: lock packages missing from the generated BUCK "
                    "(re-run `reindeer buckify` or justify in "
                    "REINDEER_OMITTED): " + ", ".join(unexpected)
                )
            if now_emitted:
                self.error(
                    "BUCK: packages now emitted that REINDEER_OMITTED still "
                    "lists (remove them from REINDEER_OMITTED): "
                    + ", ".join(now_emitted)
                )
        srcs = self.buck["srcs_entries"]
        archive_names = set(archives)
        for entry in srcs:
            if entry.startswith(":") and entry.endswith(".crate"):
                if entry[1:] not in archive_names:
                    self.error(f"BUCK: srcs references unknown archive {entry}")
        for key in archive_names:
            if f":{key}" not in srcs:
                self.error(f"BUCK: archive {key} is not referenced by any rule")

    # -- Reindeer pinning ---------------------------------------------------

    def check_reindeer(self) -> None:
        version = self.reindeer_version
        revision = version.get("revision")
        repository = version.get("repository")
        regeneration = version.get("regeneration")
        install = version.get("install")
        if not isinstance(revision, str) or not re.fullmatch(r"[0-9a-f]{40}", revision):
            self.error(f"reindeer-version.toml: revision {revision!r} is not a 40-hex git rev")
        if repository != REINDEER_REPOSITORY:
            self.error(
                f"reindeer-version.toml: repository {repository!r} != "
                f"{REINDEER_REPOSITORY!r}"
            )
        if regeneration != REGENERATION_COMMAND:
            self.error(
                f"reindeer-version.toml: regeneration command {regeneration!r} "
                f"!= canonical {REGENERATION_COMMAND!r}"
            )
        if not isinstance(install, str) or f"--rev {revision}" not in install:
            self.error(
                f"reindeer-version.toml: install command does not pin --rev {revision}"
            )
        cfg = self.reindeer_cfg
        if cfg.get("manifest_path") != "Cargo.toml":
            self.error(f"reindeer.toml: manifest_path != \"Cargo.toml\"")
        if cfg.get("third_party_dir") != ".":
            self.error(f"reindeer.toml: third_party_dir != \".\"")
        if cfg.get("vendor") is not False:
            self.error("reindeer.toml: vendor must be false (archives, not vendored)")
        if cfg.get("precise_srcs") is not True:
            self.error("reindeer.toml: precise_srcs must be true")

    # -- Auditable note -----------------------------------------------------

    def check_note(self, lock: dict[tuple[str, str], dict[str, object]]) -> None:
        note = self.note
        if note.get("format-version") != NOTE_FORMAT_VERSION:
            self.error(
                f"dependency-note.toml: format-version != {NOTE_FORMAT_VERSION}"
            )
        note_reindeer = note.get("reindeer")
        if not isinstance(note_reindeer, dict):
            self.error("dependency-note.toml: missing [reindeer] section")
            note_reindeer = {}
        for key in ("revision", "repository", "regeneration"):
            if note_reindeer.get(key) != self.reindeer_version.get(key):
                self.error(
                    f"dependency-note.toml: [reindeer] {key} is stale; "
                    "re-run `update-note`"
                )
        packages = note.get("packages")
        if not isinstance(packages, list):
            self.error("dependency-note.toml: missing [[packages]]")
            return
        by_key = {
            (p.get("name"), p.get("version")): p
            for p in packages
            if isinstance(p, dict)
        }
        libraries = self.buck["libraries"]
        alias_actual = {
            name: alias.get("actual")
            for name, alias in self.buck["aliases"].items()
        }
        for (name, version), package in lock.items():
            if "source" not in package:
                continue
            entry = by_key.get((name, version))
            if entry is None:
                self.error(
                    f"dependency-note.toml: missing entry for {name} {version}; "
                    "re-run `update-note`"
                )
                continue
            checksum = package.get("checksum")
            if entry.get("checksum") != checksum:
                self.error(
                    f"dependency-note.toml: {name} {version} checksum is stale; "
                    "re-run `update-note`"
                )
            if entry.get("source") != CANONICAL_SOURCE:
                self.error(
                    f"dependency-note.toml: {name} {version} source is stale"
                )
            library = self._library_for(name, alias_actual, libraries)
            base_features, platform_features = (
                emitted_features(library) if library is not None else ([], [])
            )
            if entry.get("features") != base_features:
                self.error(
                    f"dependency-note.toml: {name} {version} features are stale; "
                    "re-run `update-note`"
                )
            if entry.get("platform-features") != platform_features:
                self.error(
                    f"dependency-note.toml: {name} {version} platform-features "
                    "are stale; re-run `update-note`"
                )
            direct = name in DIRECT_DEPENDENCIES
            if entry.get("direct") is not direct:
                self.error(
                    f"dependency-note.toml: {name} {version} direct flag is stale"
                )
            in_buck = f"{name}-{version}.crate" in self.buck["archives"]
            if entry.get("in-buck") is not in_buck:
                self.error(
                    f"dependency-note.toml: {name} {version} in-buck flag is stale; "
                    "re-run `update-note`"
                )
            requested = entry.get("requested-features") or []
            expected_requested = self._requested_features(name)
            if sorted(requested) != sorted(expected_requested):
                self.error(
                    f"dependency-note.toml: {name} {version} requested-features "
                    "are stale; re-run `update-note`"
                )
            rust_version = entry.get("rust-version")
            if not isinstance(rust_version, str) or not (
                rust_version == "absent" or RUST_VERSION_RE.fullmatch(rust_version)
            ):
                self.error(
                    f"dependency-note.toml: {name} {version} rust-version "
                    f"{rust_version!r} is not \"absent\" or a valid version"
                )
            if self.registry_src is not None:
                actual = crate_rust_version(self.registry_src, name, version)
                if actual is None:
                    actual = "absent"
                if rust_version != actual:
                    self.error(
                        f"dependency-note.toml: {name} {version} rust-version "
                        f"{rust_version!r} does not match crate metadata {actual!r}"
                    )
        note_keys = set(by_key)
        lock_keys = {
            (name, version)
            for (name, version), package in lock.items()
            if "source" in package
        }
        for key in sorted(note_keys - lock_keys):
            self.error(
                f"dependency-note.toml: entry {key[0]} {key[1]} has no Cargo.lock "
                "package; re-run `update-note`"
            )

    def _library_for(
        self,
        name: str,
        alias_actual: dict[str, object],
        libraries: dict[str, dict[str, object]],
    ):
        actual = alias_actual.get(name)
        if isinstance(actual, str) and actual.startswith(":"):
            return libraries.get(actual[1:])
        return None

    def _requested_features(self, name: str) -> list[str]:
        dependencies = self.manifest.get("dependencies")
        if isinstance(dependencies, dict):
            spec = dependencies.get(name)
            if isinstance(spec, dict):
                features = spec.get("features")
                if isinstance(features, list) and all(
                    isinstance(f, str) for f in features
                ):
                    return features
        return []

    # -- Driver -------------------------------------------------------------

    def run(self) -> int:
        lock = self.check_lock()
        self.check_manifest(lock)
        self.check_archives(lock)
        self.check_reindeer()
        self.check_note(lock)
        if self.errors:
            for message in self.errors:
                print(f"error: {message}", file=sys.stderr)
            print(
                f"dependency integrity: FAILED ({len(self.errors)} problem(s))",
                file=sys.stderr,
            )
            return 1
        registry_count = sum("source" in p for p in lock.values())
        print(
            f"dependency integrity: passed "
            f"({registry_count} registry packages, "
            f"{len(self.buck['archives'])} http_archive rules, "
            f"{len(DIRECT_DEPENDENCIES)} direct dependencies)"
        )
        return 0


# ---------------------------------------------------------------------------
# Note generation.
# ---------------------------------------------------------------------------


def _toml_string(value: str) -> str:
    escaped = value.replace("\\", "\\\\").replace('"', '\\"')
    return f'"{escaped}"'


def generate_note(
    third_party: Path, registry_src: Path | None
) -> str:
    checker = Checker.__new__(Checker)
    checker.dir = third_party
    checker.registry_src = registry_src
    checker.errors = []
    checker.lock = load_toml(third_party / "Cargo.lock", "Cargo.lock")
    checker.manifest = load_toml(third_party / "Cargo.toml", "Cargo.toml")
    checker.reindeer_version = load_toml(
        third_party / "reindeer-version.toml", "reindeer-version.toml"
    )
    checker.buck = parse_buck(third_party / "BUCK")
    lock = checker.check_lock()
    if checker.errors:
        raise IntegrityError(
            "cannot generate note: Cargo.lock/BUCK checks failed:\n  "
            + "\n  ".join(checker.errors)
        )
    libraries = checker.buck["libraries"]
    alias_actual = {
        name: alias.get("actual")
        for name, alias in checker.buck["aliases"].items()
    }
    lines = [
        "# Machine-readable audit note for the buck2-nextest-adapter",
        "# third-party graph. Do not edit by hand: regenerate with",
        "#   python3 third-party/check_dependencies.py update-note third-party",
        "#",
        "# rust-version is the crate's declared MSRV when it could be read from",
        "# a local cargo registry checkout (--registry-src); \"absent\" means the",
        "# crate declares none or the source was unavailable at generation time.",
        "# features are the features reindeer emitted in BUCK (base), with",
        "# platform-features being the union of per-platform additions; in-buck",
        "# records whether the package is materialized as an http_archive.",
        f"format-version = {NOTE_FORMAT_VERSION}",
        "",
        "[reindeer]",
        f"revision = {_toml_string(str(checker.reindeer_version['revision']))}",
        f"repository = {_toml_string(str(checker.reindeer_version['repository']))}",
        f"regeneration = {_toml_string(str(checker.reindeer_version['regeneration']))}",
        "",
        "[[packages]]",
    ]
    entries: list[tuple[str, str, str]] = []
    for (name, version), package in sorted(lock.items()):
        if "source" not in package:
            continue
        entries.append((name, version, str(package["checksum"])))
    first = True
    for name, version, checksum in entries:
        if not first:
            lines.append("")
            lines.append("[[packages]]")
        first = False
        library = None
        actual = alias_actual.get(name)
        if isinstance(actual, str) and actual.startswith(":"):
            library = libraries.get(actual[1:])
        base_features, platform_features = (
            emitted_features(library) if library is not None else ([], [])
        )
        rust_version = "absent"
        if registry_src is not None:
            value = crate_rust_version(registry_src, name, version)
            if value is not None:
                rust_version = value
        direct = name in DIRECT_DEPENDENCIES
        requested = checker._requested_features(name) if direct else []
        lines.append(f"name = {_toml_string(name)}")
        lines.append(f"version = {_toml_string(version)}")
        lines.append(f"checksum = {_toml_string(checksum)}")
        lines.append(f"source = {_toml_string(CANONICAL_SOURCE)}")
        lines.append(f"rust-version = {_toml_string(rust_version)}")
        lines.append(
            f"in-buck = {'true' if f'{name}-{version}.crate' in checker.buck['archives'] else 'false'}"
        )
        lines.append(f"direct = {'true' if direct else 'false'}")
        lines.append(
            "features = ["
            + ", ".join(_toml_string(f) for f in base_features)
            + "]"
        )
        lines.append(
            "platform-features = ["
            + ", ".join(_toml_string(f) for f in platform_features)
            + "]"
        )
        lines.append(
            "requested-features = ["
            + ", ".join(_toml_string(f) for f in sorted(requested))
            + "]"
        )
    lines.append("")
    return "\n".join(lines)


def main(argv: list[str]) -> int:
    if len(argv) < 3 or argv[1] not in ("check", "update-note"):
        print(__doc__, file=sys.stderr)
        return 2
    command = argv[1]
    third_party = Path(argv[2]).resolve()
    registry_src: Path | None = None
    if "--registry-src" in argv:
        index = argv.index("--registry-src")
        if index + 1 >= len(argv):
            print("error: --registry-src requires a directory", file=sys.stderr)
            return 2
        registry_src = Path(argv[index + 1]).expanduser().resolve()
    if command == "update-note":
        try:
            content = generate_note(third_party, registry_src)
        except IntegrityError as error:
            print(f"error: {error}", file=sys.stderr)
            return 1
        target = third_party / "dependency-note.toml"
        target.write_text(content, encoding="utf-8")
        print(f"dependency note: wrote {target}")
        return 0
    try:
        checker = Checker(third_party, registry_src)
    except IntegrityError as error:
        print(f"error: {error}", file=sys.stderr)
        return 1
    return checker.run()


if __name__ == "__main__":
    sys.exit(main(sys.argv))
